INSERT INTO site_pages (page_name, content_json) VALUES ('global', '{"nav":{"logo_image":"/assets/img/catering-menu-logo.png","logo_icon":"fas fa-utensils","logo_text":"Catering Menu","links":[{"label":"Home","url":"/"},{"label":"Caterers","url":"/listings"},{"label":"About Us","url":"/about"},{"label":"FAQs","url":"/faqs"},{"label":"Contact","url":"/contact"}],"cta_btn":{"label":"List Your Business","url":"/get-listed"}},"footer":{"about_heading":"About Catering Menu","about_text":"Catering Menu is the premier discovery directory connecting event planners and hosts with top-rated caterers, verified menus, genuine reviews, and seamless booking inquiries for unforgettable celebrations.","quick_heading":"Quick Links","quick_links":[{"label":"Home","url":"/"},{"label":"Caterers","url":"/listings"},{"label":"About Us","url":"/about"},{"label":"List Your Business","url":"/get-listed"},{"label":"FAQs","url":"/faqs"},{"label":"Contact","url":"/contact"}],"cuisines_heading":"Popular Catering","cuisine_links":[{"label":"Wedding Catering","url":"/listings/wedding"},{"label":"Corporate Galas","url":"/listings/corporate"},{"label":"Live BBQ & Grill Stations","url":"/listings/bbq"},{"label":"Italian & Wood-Fired","url":"/listings/italian"},{"label":"Royal Indian & Asian","url":"/listings/asian"},{"label":"Cocktails & Canapés","url":"/listings/cocktail"}],"legal_heading":"Legal & Policy","legal_links":[{"label":"Privacy Policy","url":"/privacy"},{"label":"Terms of Service","url":"/terms"},{"label":"Disclaimer","url":"/disclaimer"}],"show_socials":false,"socials":[],"copyright":"\u00a9 2026 Catering Menu. All rights reserved."}}');
INSERT INTO site_pages (page_name, content_json) VALUES ('home', '{"hero":{"badge":"Premier Catering Directory","title":"Discover Extraordinary Catering Experiences","subtitle":"Explore handpicked caterers, browse exquisite event menus, and find the perfect culinary service for your wedding, corporate event, or private party.","search_placeholder":"Search caterers by name, cuisine, or occasion...","search_btn":{"label":"Explore Now","url":"#restaurants"},"stats":[{"number":"2,500+","label":"Caterers Listed"},{"number":"15,000+","label":"Curated Menus"},{"number":"50,000+","label":"Happy Guests Served"}]},"how_it_works":{"overline":"Simple Process","title":"How Catering Menu Works","subtitle":"Booking the ideal catering for your event is effortless in three simple steps.","steps":[{"icon":"fas fa-search","title":"Browse & Discover","text":"Explore top-rated caterers. Filter by cuisine, event type, or guest capacity to find your ideal match."},{"icon":"fas fa-book-open","title":"Explore Menus & Reviews","text":"Browse detailed food menus, buffet items, and verified reviews from past event hosts."},{"icon":"fas fa-phone-volume","title":"Connect & Plan","text":"Get in touch directly with the caterer, customize your menu, and create unforgettable moments."}]},"featured":{"overline":"Top Rated","title":"Featured Catering Services","subtitle":"Handpicked catering partners for weddings, corporate galas, and special celebrations.","view_all_btn":{"label":"View All Caterers","url":"/listings"}},"split_1":{"overline":"Why Choose Us","title":"Curated Catering Teams for Every Occasion","text":"Every catering service on Catering Menu is handpicked by our culinary experts. We visit, taste, and verify kitchen standards and event execution before feature approval. Our rigorous selection process ensures your guests enjoy nothing short of culinary perfection.","bullets":[{"icon":"fas fa-check-circle","text":"Handpicked & verified catering partners"},{"icon":"fas fa-check-circle","text":"Customizable multi-course event menus"},{"icon":"fas fa-check-circle","text":"Live food counters & buffet setups"},{"icon":"fas fa-check-circle","text":"Authentic verified host reviews & photos"}],"image_url":"https:\/\/images.unsplash.com\/photo-1555244162-803834f70033?w=800","image_alt":"Luxury catering buffet setup","btn":{"label":"Learn More","url":"/about"}},"split_2":{"overline":"Community Driven","title":"Real Reviews from Real Event Hosts","text":"From weddings to corporate conferences, over 50,000 event hosts share authentic experiences, setup photos, and honest reviews. Make confident choices backed by genuine guest satisfaction scores.","bullets":[{"icon":"fas fa-shield-alt","text":"100% verified host reviews"},{"icon":"fas fa-users","text":"50,000+ active event planners"},{"icon":"fas fa-camera","text":"Photos of real buffets & live counters"},{"icon":"fas fa-trophy","text":"Top caterer excellence recognition"}],"image_url":"https:\/\/images.unsplash.com\/photo-1511795409834-ef04bbd61622?w=800","image_alt":"Guests enjoying catering at celebration","btn":{"label":"Browse Reviews","url":"/listings"}},"cta":{"title":"Own a Catering Business?","text":"Join Catering Menu and connect with thousands of event organizers, wedding planners, and corporate hosts looking for exceptional food services.","btn":{"label":"List Your Business Today","url":"/get-listed"}}}');
INSERT INTO site_pages (page_name, content_json) VALUES ('about', '{"hero":{"title":"About Catering Menu","subtitle":"Connecting event hosts, planners, and families with unforgettable catering experiences."},"mission":{"title":"Our Mission","text":"To empower event planners and food lovers with the tools, verified menus, and transparent host reviews needed to book exceptional catering services with total confidence. We believe every celebration deserves remarkable food and hospitality."},"vision":{"title":"Our Vision","text":"To become the world''s most trusted catering discovery and booking platform, where quality craftsmanship, verified client reviews, and culinary passion bring unforgettable feasts to life for every occasion."},"stats":[{"number":"2,500+","label":"Caterers Listed"},{"number":"15,000+","label":"Curated Menus"},{"number":"50,000+","label":"Happy Event Guests"},{"number":"120+","label":"Cities Covered"}],"cta":{"title":"Own a Catering Business?","text":"Join Catering Menu and reach thousands of event planners and hosts.","btn":{"label":"List Your Business Today","url":"/get-listed"}}}');
