INSERT INTO site_pages (page_name, content_json) VALUES ('get-listed', '{"hero":{"title":"List Your Catering Business","subtitle":"Join thousands of caterers already on Catering Menu. Showcase your event menus, gather host reviews, and attract bookings."},"form":{"title":"Submit Your Catering Business","name_label":"Catering Business Name","banner_label":"Banner Image URL","about_label":"About Your Catering Business","menu_label":"Direct Menu Text","days_label":"Opening Days & Hours","locations_label":"Location(s)","submit_btn":{"label":"Submit for Review","url":"#"},"success_msg":"Thank you! Your catering business has been submitted for review. Our team will approve it shortly."}}');
INSERT INTO site_pages (page_name, content_json) VALUES ('faqs', '{"hero":{"title":"Frequently Asked Questions","subtitle":"Everything you need to know about using Catering Menu."},"items":[{"question":"How do I list my catering business on Catering Menu?","answer":"Simply navigate to the List Your Business page and fill out the submission form with your catering service details. Our team will review your submission and approve it within 24-48 hours. Once approved, your catering profile will appear on the platform for thousands of event planners to discover."},{"question":"Is it free to list my catering business?","answer":"Yes! Listing your catering business on Catering Menu is completely free. We believe in making quality catering discovery accessible to everyone."},{"question":"How do client reviews work on Catering Menu?","answer":"Anyone who has hosted an event with a caterer can leave a review. Reviews include a star rating and written feedback. Our moderation team ensures all reviews are authentic and verified."},{"question":"Can I edit my catering profile after submission?","answer":"Yes. After your listing is approved, you can log in to the admin panel or contact our support team to update menus, photos, service areas, or contact details."}],"cta":{"title":"Own a Catering Business?","text":"Join Catering Menu and reach thousands of event planners and hosts.","btn":{"label":"List Your Business Today","url":"/get-listed"}}}');
INSERT INTO site_pages (page_name, content_json) VALUES ('restaurant', '{"welcome_title":"About","menu_title":"Our Catering Menu","menu_toggle_file":"View Uploaded Menu","menu_toggle_text":"View Text Menu","info_title":"Catering Info","hours_label":"Operating Hours","location_label":"Kitchen & Service Locations","reviews_title":"Host Reviews & Ratings","review_form_title":"Leave a Review for this Caterer","review_form_name":"Your Name","review_form_rating":"Your Rating","review_form_text":"Your Review","review_form_btn":{"label":"Submit Review","url":"#"},"review_success":"Your review has been submitted successfully!","no_reviews":"No reviews yet. Be the first to share your experience with this caterer!"}');
INSERT INTO site_pages (page_name, content_json) VALUES ('privacy', '{"hero":{"title":"Privacy Policy"},"content":"At Catering Menu, we are committed to protecting your privacy. This Privacy Policy explains how we collect, use, disclose, and safeguard your information when you visit our website and use our services.\n\nWe collect personal information such as your name, email address, and catering preferences only when you voluntarily provide it. This information is used to personalize your experience, improve our platform, and communicate with you about catering recommendations, updates, and bookings.\n\nWe do not sell, trade, or rent your personal information to third parties. We implement appropriate security measures to protect your personal information from unauthorized access, alteration, disclosure, or destruction.\n\nOur website uses cookies to enhance your browsing experience. You can choose to disable cookies through your browser settings. By using Catering Menu, you consent to our Privacy Policy."}');
INSERT INTO site_pages (page_name, content_json) VALUES ('terms', '{"hero":{"title":"Terms of Service"},"content":"Welcome to Catering Menu. By accessing or using our website and services, you agree to be bound by these Terms of Service.\n\nCatering Menu provides a platform for discovering catering services, exploring menus, and sharing client reviews. You may use our services only for lawful purposes and in accordance with these Terms.\n\nYou are responsible for maintaining the confidentiality of your account credentials and for all activities that occur under your account. Reviews submitted to Catering Menu must be based on genuine personal experiences.\n\nCatering business owners are responsible for the accuracy of their listed menus, pricing, and service descriptions. Catering Menu reserves the right to modify, suspend, or discontinue any part of the service at any time without prior notice."}');
INSERT INTO site_pages (page_name, content_json) VALUES ('disclaimer', '{"hero":{"title":"Disclaimer"},"content":"The information provided on Catering Menu is for general informational purposes only. While we strive to keep catering information accurate and up-to-date, we make no representations or warranties of any kind about the completeness, accuracy, reliability, or availability of the information contained on this platform.\n\nCatering listings, menus, pricing, and event services are provided by the caterers themselves and may change without notice. Catering Menu does not guarantee the performance or service of any listed caterer.\n\nUser reviews reflect individual opinions and do not represent the views of Catering Menu. We encourage event hosts to verify all details directly with the caterer before booking."}');
