INSERT INTO restaurants (status, restaurant_json) VALUES ('approved', '{"name":"La Maison Dor\u00e9e","slug":"la-maison-doree","cuisine":"French Catering","lat":40.758,"lng":-73.9855,"banner_url":"https:\/\/images.unsplash.com\/photo-1517248135467-4c7edcad34c4?w=1400","about_text":"Nestled in the heart of downtown, La Maison Dor\u00e9e is a beacon of French culinary excellence. With over two decades of catering experience for luxury galas and high-profile receptions, our kitchen has been led by award-winning Chef Antoine Beaumont, who brings classical French techniques together with locally sourced seasonal ingredients.","direct_menu_text":"\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n         LA MAISON DOR\u00c9E \u2014 CATERING MENU\n\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n\n\u2500\u2500 PASSED HORS D''OEUVRES \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nSeared Foie Gras with Brioche\nEscargots Tartlets\nTuna Tartare with Avocado Caviar\n\n\u2500\u2500 PLATED DINNER \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nDuck Confit with Braised Lentils\nFilet Mignon with Black Truffle Reduction\nPan-Seared Chilean Sea Bass\nHerb-Crusted Colorado Rack of Lamb\n\n\u2500\u2500 DESSERT STATIONS \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nCr\u00e8me Br\u00fbl\u00e9e Flamb\u00e9 Bar\nMini Chocolate Souffl\u00e9 Bites\nArtisanal French Cheese Display","menu_file_path":"","opening_days":"Mon-Sun: 9:00 AM \u2013 9:00 PM","locations":"742 Evergreen Ave, Downtown | Serves Tri-State Area","reviews":[{"name":"Sarah Mitchell","rating":5,"date":"2025-12-15","text":"Incredible catering service for our daughter''s wedding. The duck confit and dessert bar wowed every single guest."},{"name":"James Rodriguez","rating":5,"date":"2025-11-28","text":"Chef Antoine and his team were prompt, polished, and exceptionally professional at our corporate annual gala."}]}');
INSERT INTO restaurants (status, restaurant_json) VALUES ('approved', '{"name":"Sakura Japanese Kitchen","slug":"sakura-japanese-kitchen","cuisine":"Japanese Catering","lat":40.7282,"lng":-73.7949,"banner_url":"https:\/\/images.unsplash.com\/photo-1579027989536-b7b1f875659b?w=1400","about_text":"Sakura Japanese Kitchen brings live sushi bar catering and authentic Japanese dining to private residences and corporate galas. Our master sushi chefs craft fresh nigiri, specialty rolls, and sizzling teppanyaki live for your guests.","direct_menu_text":"\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n    SAKURA JAPANESE \u2014 EVENT CATERING\n\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n\n\u2500\u2500 LIVE SUSHI BAR DISPLAY \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nBluefin Tuna & Salmon Nigiri\nDragon & Rainbow Specialty Rolls\nYellowtail Jalape\u00f1o Sashimi\n\n\u2500\u2500 HOT BUFFET & TEPPANYAKI \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nWagyu Beef Skewers\nBlack Cod Miso\nCrispy Vegetable Gyoza\n\n\u2500\u2500 SAKE & BEVERAGE STATION \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nJunmai Daiginjo Sake Tasting\nJapanese Highball Cocktails\nMatcha Green Tea Tiramisu","menu_file_path":"","opening_days":"Tue-Sun: 10:00 AM \u2013 10:00 PM","locations":"88 Cherry Blossom Lane, East Side | Serves Metro Area","reviews":[{"name":"Mike Tanaka","rating":5,"date":"2026-01-10","text":"The live sushi counter was the absolute highlight of our company summit. Extremely fresh fish and pristine presentation."}]}');
INSERT INTO restaurants (status, restaurant_json) VALUES ('approved', '{"name":"The Copper Grill","slug":"the-copper-grill","cuisine":"American BBQ Catering","lat":40.7484,"lng":-73.9857,"banner_url":"https:\/\/images.unsplash.com\/photo-1466978913421-dad2ebd01d17?w=1400","about_text":"The Copper Grill provides live-fire barbecue catering, wood-smoked carving stations, and upscale rustic hospitality for outdoor weddings, corporate picnics, and gatherings.","direct_menu_text":"\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n     THE COPPER GRILL \u2014 BBQ CATERING\n\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n\n\u2500\u2500 LIVE CARVING STATION \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\n14-Hour Smoked Prime Brisket\nSlow-Roasted Pulled Pork\nFlame-Grilled Free-Range Chicken\n\n\u2500\u2500 GOURMET SIDES \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nTruffle Four-Cheese Macaroni\nSmoked Sweet Corn Chowder\nArtisanal Skillet Cornbread with Honey Butter","menu_file_path":"","opening_days":"Mon-Sun: 9:00 AM \u2013 9:00 PM","locations":"420 Industrial Way, Warehouse District | Serves Greater Metro Area","reviews":[{"name":"Robert Johnson","rating":5,"date":"2026-02-01","text":"The brisket melted in everyone''s mouth. Best barbecue catering our team has ever experienced."}]}');
INSERT INTO restaurants (status, restaurant_json) VALUES ('approved', '{"name":"Verde Trattoria","slug":"verde-trattoria","cuisine":"Italian Catering","lat":40.7178,"lng":-73.9988,"banner_url":"https:\/\/images.unsplash.com\/photo-1414235077428-338989a2e8c0?w=1400","about_text":"Verde Trattoria provides authentic Italian family-style catering, wood-fired pizza ovens on wheels, and handcrafted pasta bars for private parties, rehearsal dinners, and weddings.","direct_menu_text":"\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\r\n     VERDE TRATTORIA \u2014 ITALIAN CATERING\r\n\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\r\n\r\n\u2500\u2500 ANTIPASTI GRAZING TABLE \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\r\n\r\nImported Prosciutto di Parma & Burrata\r\nBruschetta al Pomodoro e Basilico\r\nMarinated Artichokes & Olives\r\n\r\n\u2500\u2500 LIVE PASTA WHEEL & WOOD OVEN \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\r\n\r\nParmesano Reggiano Fettuccine Wheel\r\nPappardelle al Rag\u00f9 di Cinghiale\r\nNeapolitan Pizza Station","menu_file_path":"","opening_days":"Mon-Sun: 10:00 AM \u2013 9:00 PM","locations":"15 Olive Garden Blvd | Serves All Boroughs","reviews":[{"name":"Rachel Green","rating":5,"date":"2026-01-25","text":"The cheese wheel pasta station was an unforgettable experience at our anniversary party."}]}');
INSERT INTO restaurants (status, restaurant_json) VALUES ('approved', '{"name":"Spice Route","slug":"spice-route","cuisine":"Indian & Asian Catering","lat":40.7359,"lng":-73.9911,"banner_url":"https:\/\/images.unsplash.com\/photo-1514933651103-005eec06c04b?w=1400","about_text":"Spice Route specializes in grand Indian and South Asian wedding catering, corporate lunches, live tandoor stations, and multi-regional culinary banquets.","direct_menu_text":"\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\r\n      SPICE ROUTE \u2014 ROYAL WEDDING CATERING\r\n\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\r\n\r\n\u2500\u2500 LIVE CHATPATI CHAAT COUNTER \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\r\n\r\nPani Puri Shots with Flavored Waters\r\nDahi Bhalla Papdi Chaat\r\nCocktail Samosas & Mint Chutney\r\n\r\n\u2500\u2500 LIVE TANDOOR & CURRY BANQUET \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\r\n\r\nMurgh Malai Tikka & Seekh Kebabs\r\nRoyal Butter Chicken\r\nAwadhi Dum Biryani with Burani Raita\r\nPaneer Tikka Masala & Dal Makhani\r\n\r\n\u2500\u2500 DESSERT ROYALE \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\r\n\r\nWarm Gulab Jamun with Rabdi\r\nKesar Pista Kulfi Sticks\r\nAssorted Baklava Towers","menu_file_path":"","locations":"225 Spice Market Road | Available Across Tri-State Region","reviews":[{"name":"Priya Sharma","rating":5,"date":"2026-02-10","text":"Spice Route catered our 400-guest wedding and blew everyone away. The live chaat counter and butter chicken were incredible!"}]}');
